export const displayName = 'Aide & FAQ';
export const screenSize = 'mobile';

import Icon from '@global/Icon';

const faqs = [
  {
    question: 'Comment créer une chanson ?',
    answer: 'Pour créer une chanson, cliquez sur le bouton "Créer" depuis l\'écran d\'accueil. Suivez les étapes pour sélectionner votre style musical et votre occasion spéciale, puis notre IA générera une chanson unique pour vous.'
  },
  {
    question: 'Combien de chansons puis-je créer ?',
    answer: 'Le nombre de chansons dépend de votre plan d\'abonnement. Le plan Populaire vous permet de créer 5 chansons par mois.'
  },
  {
    question: 'Puis-je télécharger mes chansons ?',
    answer: 'Oui, vous pouvez télécharger vos chansons générées au format MP3 directement depuis votre bibliothèque "Mes chansons".'
  },
  {
    question: 'Comment fonctionne le système de crédit ?',
    answer: 'Chaque création de chanson consomme un crédit. Vous obtenez des crédits avec votre abonnement et vous pouvez en acheter des supplémentaires selon vos besoins.'
  },
  {
    question: 'Puis-je partager mes chansons ?',
    answer: 'Absolument ! Vous pouvez partager vos chansons sur les réseaux sociaux ou avec vos amis via un lien direct depuis la page de chaque chanson.'
  },
  {
    question: 'Que faire si j\'ai un problème technique ?',
    answer: 'Si vous rencontrez un problème, veuillez contacter notre équipe de support via le formulaire "Contacter le support" dans les paramètres de votre profil.'
  }
];

export default function HelpFAQScreen() {
  return (
    <div className="bg-background flex flex-col">
      {/* Top Nav */}
      <div className="bg-background border-b border-border px-4 py-3 flex items-center justify-between">
        <button className="flex items-center gap-1.5 text-sm font-semibold text-foreground">
          <Icon i="arrow-left" size={18} /> {t('Retour')}
        </button>
        <span className="text-sm font-medium text-muted-foreground">{t('Aide & FAQ')}</span>
      </div>

      {/* Content */}
      <div className="flex-1 px-4 py-6 overflow-y-auto space-y-4">
        {/* Header */}
        <div className="mb-6">
          <h2 className="font-headings font-bold text-xl text-foreground mb-2">{t('Questions fréquemment posées')}</h2>
          <p className="text-sm text-muted-foreground">{t('Trouvez les réponses à vos questions sur Musika.')}</p>
        </div>

        {/* FAQs */}
        <div className="space-y-3 pb-6">
          {faqs.map((faq, index) => (
            <details key={index} className="group">
              <summary className="bg-card border border-border rounded-xl px-4 py-3 flex items-center justify-between cursor-pointer list-none">
                <span className="text-sm font-medium text-foreground pr-2">{faq.question}</span>
                <Icon i="chevron-down" size={18} className="text-muted-foreground group-open:rotate-180 transition-transform" />
              </summary>
              <div className="bg-input border border-border border-t-0 rounded-b-xl px-4 py-3 mt-0">
                <p className="text-sm text-muted-foreground">{faq.answer}</p>
              </div>
            </details>
          ))}
        </div>

        {/* Contact Support */}
        <div className="bg-secondary/40 border border-secondary rounded-xl p-4 mt-6">
          <div className="flex items-start gap-3 mb-3">
            <Icon i="mail" size={20} className="text-primary flex-shrink-0 mt-0.5" />
            <div>
              <h3 className="font-bold text-sm text-foreground">{t('Vous n\'avez pas trouvé votre réponse ?')}</h3>
              <p className="text-xs text-muted-foreground mt-1">{t('Contactez notre équipe de support, nous sommes là pour vous aider.')}</p>
            </div>
          </div>
          <button className="w-full py-2.5 bg-primary text-primary-foreground font-semibold text-sm rounded-lg">
            {t('Contacter le support')}
          </button>
        </div>
      </div>
    </div>
  );
}

export const displayName = 'Mes Chansons Générées';
export const screenSize = 'mobile';

import MobileTopBar from '@components/MobileTopBar';
import MobileBottomNav from '@components/MobileBottomNav';
import Icon from '@global/Icon';

const generatedSongs = [
  {
    id: 1,
    title: 'Pour toi Mariam',
    occasion: 'Anniversaire',
    style: 'Afrobeat',
    date: '21 juillet 2025',
    versions: [
      { label: 'Version 1', duration: '1m 32s', plays: 14, liked: true },
      { label: 'Version 2', duration: '1m 45s', plays: 8, liked: false },
    ],
  },
  {
    id: 2,
    title: 'Mon mariage',
    occasion: 'Mariage',
    style: 'Amapiano',
    date: '20 juillet 2025',
    versions: [
      { label: 'Version 1', duration: '1m 48s', plays: 22, liked: true },
      { label: 'Version 2', duration: '1m 55s', plays: 5, liked: false },
    ],
  },
  {
    id: 3,
    title: 'Gloire à Dieu',
    occasion: 'Hommage',
    style: 'Gospel',
    date: '19 juillet 2025',
    versions: [
      { label: 'Version 1', duration: '2m 04s', plays: 31, liked: true },
      { label: 'Version 2', duration: '1m 58s', plays: 18, liked: true },
    ],
  },
];

const styleColors = {
  'Afrobeat': 'bg-orange-50 text-coral',
  'Amapiano': 'bg-secondary text-primary',
  'Gospel': 'bg-green-50 text-success',
  'R&B': 'bg-purple-50 text-purple-600',
  'Zouglou': 'bg-yellow-50 text-yellow-700',
};

export default function MySongsGenerated() {
  return (
    <div className="bg-background flex flex-col font-body">
      <MobileTopBar credits={3} />

      {/* Header */}
      <div className="px-4 pt-4 pb-4">
        <div className="flex items-center justify-between mb-1">
          <h1 className="font-headings font-bold text-2xl text-foreground">{t('Mes chansons')}</h1>
          <button className="bg-primary text-primary-foreground text-xs font-semibold px-3 py-2 rounded-lg flex items-center gap-1.5">
            <Icon i="plus" size={13} />
            {t('Créer')}
          </button>
        </div>
        <p className="text-sm text-muted-foreground">{t('3 chansons · 6 versions générées')}</p>
      </div>

      {/* Filter Bar */}
      <div className="px-4 pb-4 flex gap-2">
        <div className="flex-1 flex items-center gap-2 bg-input border border-border rounded-lg px-3 py-2">
          <Icon i="search" size={14} className="text-muted-foreground" />
          <span className="text-sm text-muted-foreground">{t('Rechercher une chanson…')}</span>
        </div>
        <button className="flex items-center gap-1.5 border border-border rounded-lg px-3 py-2 bg-input">
          <Icon i="sliders-horizontal" size={14} className="text-muted-foreground" />
        </button>
      </div>

      {/* Sort Tabs */}
      <div className="px-4 pb-4 flex gap-2">
        {[t('Toutes'), t('Récentes'), t('Favorites')].map((tab, i) => (
          <button key={tab} className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${i === 0 ? 'bg-primary text-primary-foreground' : 'bg-input border border-border text-muted-foreground'}`}>
            {tab}
          </button>
        ))}
      </div>

      {/* Song Cards */}
      <div className="px-4 flex flex-col gap-4 pb-28">
        {generatedSongs.map((song) => (
          <div key={song.id} className="bg-card border border-border rounded-xl overflow-hidden"
            style={{ boxShadow: '0 2px 12px rgba(0,0,0,0.06)' }}>

            {/* Card Header */}
            <div className="px-4 pt-4 pb-3 flex items-start justify-between">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <h2 className="font-headings font-bold text-base text-foreground truncate">{song.title}</h2>
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                  <span className={`text-xs font-semibold px-2 py-0.5 rounded-md ${styleColors[song.style] || 'bg-muted text-muted-foreground'}`}>
                    {song.style}
                  </span>
                  <span className="text-xs text-muted-foreground">{song.occasion}</span>
                  <span className="text-xs text-muted-foreground">· {song.date}</span>
                </div>
              </div>
              <button className="text-muted-foreground ml-2 mt-0.5">
                <Icon i="more-vertical" size={18} />
              </button>
            </div>

            {/* Divider */}
            <div className="border-t border-border mx-4" />

            {/* Versions */}
            <div className="px-4 py-3 flex flex-col gap-2">
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-1">{t('Versions')}</p>
              {song.versions.map((v, vi) => (
                <div key={vi} className={`flex items-center gap-3 px-3 py-2.5 rounded-lg ${vi === 0 ? 'bg-secondary border border-primary/15' : 'bg-input border border-border'}`}>
                  {/* Play Button */}
                  <button className={`w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0 ${vi === 0 ? 'bg-primary' : 'bg-muted'}`}>
                    <Icon i="play" size={14} className={vi === 0 ? 'text-primary-foreground' : 'text-muted-foreground'} />
                  </button>

                  {/* Version Info + Waveform */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-1">
                      <span className={`text-sm font-semibold ${vi === 0 ? 'text-primary' : 'text-foreground'}`}>{v.label}</span>
                      <span className="text-xs text-muted-foreground">{v.duration}</span>
                    </div>
                    {/* Mini waveform */}
                    <div className="flex items-end gap-0.5 h-4">
                      {[3, 6, 4, 9, 7, 5, 10, 8, 6, 9, 5, 7, 4, 8, 6, 10, 7, 5, 8, 4].map((h, i) => (
                        <div key={i}
                          className={`w-1 rounded-sm ${vi === 0 ? 'bg-primary/40' : 'bg-muted-foreground/30'}`}
                          style={{ height: `${h}px` }} />
                      ))}
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-1.5 flex-shrink-0">
                    <span className="text-xs text-muted-foreground">{v.plays}</span>
                    <button className={v.liked ? 'text-red-400' : 'text-muted-foreground'}>
                      <Icon i={v.liked ? 'heart' : 'heart'} size={15} />
                    </button>
                    <button className="text-muted-foreground">
                      <Icon i="share-2" size={15} />
                    </button>
                    <button className="text-muted-foreground">
                      <Icon i="download" size={15} />
                    </button>
                  </div>
                </div>
              ))}
            </div>

            {/* Card Footer Actions */}
            <div className="border-t border-border mx-4 mb-3" />
            <div className="px-4 pb-3 flex items-center gap-2">
              <button className="flex-1 flex items-center justify-center gap-1.5 py-2 bg-input border border-border rounded-lg text-xs font-semibold text-foreground">
                <Icon i="pencil" size={12} />
                {t('Modifier paroles')}
              </button>
              <button className="flex-1 flex items-center justify-center gap-1.5 py-2 bg-input border border-border rounded-lg text-xs font-semibold text-foreground">
                <Icon i="refresh-cw" size={12} />
                {t('Regénérer')}
              </button>
              <button className="flex items-center justify-center w-9 h-9 bg-red-50 border border-red-100 rounded-lg flex-shrink-0">
                <Icon i="trash-2" size={14} className="text-red-400" />
              </button>
            </div>
          </div>
        ))}
      </div>

      <MobileBottomNav activeTab={t('Mes chansons')} />
    </div>
  );
}

export const displayName = 'Centre de notifications';
export const screenSize = 'mobile';

import Icon from '@global/Icon';

const notifications = [
  {
    id: 1,
    type: 'music',
    title: 'Génération terminée',
    message: 'Votre chanson "Danse la Nuit" est prête à écouter !',
    time: 'Il y a 2h',
    unread: true
  },
  {
    id: 2,
    type: 'heart',
    title: 'Nouvelles likes',
    message: 'Votre chanson "Pour toi Mariam" a reçu 12 likes.',
    time: 'Il y a 5h',
    unread: true
  },
  {
    id: 3,
    type: 'play',
    title: 'Nouvelles écoutes',
    message: 'Votre chanson "Rêve d\'Afrique" a été écoutée 45 fois.',
    time: 'Hier',
    unread: false
  },
  {
    id: 4,
    type: 'bell',
    title: 'Concours du mois',
    message: 'Participez à notre concours mensuel et gagnez des crédits !',
    time: 'Il y a 2 jours',
    unread: false
  },
  {
    id: 5,
