    title: 'Promotion spéciale',
    message: 'Profitez de 20% de réduction sur votre prochain abonnement.',
    time: 'Il y a 3 jours',
    unread: false
  }
];

const getIcon = (type) => {
  const iconMap = {
    music: 'music',
    heart: 'heart',
    play: 'play',
    bell: 'bell',
    mail: 'mail'
  };
  return iconMap[type] || 'bell';
};

export default function NotificationCenterScreen() {
  return (
    <div className="bg-background flex flex-col">
      {/* Top Nav */}
      <div className="bg-background border-b border-border px-4 py-3 flex items-center justify-between">
        <button className="flex items-center gap-1.5 text-sm font-semibold text-foreground">
          <Icon i="arrow-left" size={18} /> {t('Retour')}
        </button>
        <span className="text-sm font-medium text-muted-foreground">{t('Notifications')}</span>
        <button className="text-sm font-semibold text-primary">{t('Marquer tout')}</button>
      </div>

      {/* Content */}
      <div className="flex-1 px-4 py-4 overflow-y-auto space-y-2">
        {notifications.map((notif) => (
          <button
            key={notif.id}
            className={`w-full flex gap-3 p-3 rounded-xl border transition-colors ${
              notif.unread
                ? 'bg-secondary/20 border-secondary'
                : 'bg-card border-border'
            }`}
          >
            <div className={`flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center ${
              notif.unread ? 'bg-primary' : 'bg-muted'
            }`}>
              <Icon i={getIcon(notif.type)} size={18} className={notif.unread ? 'text-primary-foreground' : 'text-muted-foreground'} />
            </div>
            <div className="flex-1 text-left min-w-0">
              <div className="flex items-start justify-between gap-2">
                <h3 className="font-semibold text-sm text-foreground">{notif.title}</h3>
                {notif.unread && <div className="w-2 h-2 bg-primary rounded-full flex-shrink-0 mt-1.5"></div>}
              </div>
              <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{notif.message}</p>
              <p className="text-xs text-muted-foreground mt-1">{notif.time}</p>
            </div>
          </button>
        ))}
      </div>

      {/* Empty state message if no notifications */}
      <div className="flex-1 flex items-center justify-center px-4 py-8">
        {/* This div is for layout balance - would be hidden if notifications exist */}
      </div>
    </div>
  );
}

