                </div>
              </div>
              <button className="absolute top-2 right-2 w-8 h-8 bg-primary rounded-lg flex items-center justify-center hover:bg-primary/90">
                <Icon i="play" size={12} className="text-primary-foreground" />
              </button>
            </div>
          ))}
