export const displayName = 'Éditer le profil';
export const screenSize = 'mobile';

import Icon from '@global/Icon';

export default function EditProfileScreen() {
  return (
    <div className="bg-background flex flex-col">
      {/* Top Nav */}
      <div className="bg-background border-b border-border px-4 py-3 flex items-center justify-between">
        <button className="flex items-center gap-1.5 text-sm font-semibold text-foreground">
          <Icon i="arrow-left" size={18} /> {t('Retour')}
        </button>
        <span className="text-sm font-medium text-muted-foreground">{t('Éditer profil')}</span>
      </div>

      {/* Content */}
      <div className="flex-1 px-4 py-6 overflow-y-auto space-y-5">
        {/* Name */}
