        </div>

        {/* Location */}
        <div>
          <label className="text-xs font-bold text-muted-foreground uppercase">{t('Localisation')}</label>
          <div className="border border-border rounded-lg px-3 py-3 mt-2 bg-input">
            <p className="text-sm text-foreground">{t('Abidjan, Côte d\'Ivoire')}</p>
          </div>
        </div>

      </div>

      {/* CTA */}
      <div className="px-4 py-4 bg-background space-y-2">
        <button className="w-full py-4 bg-primary text-primary-foreground font-bold text-base rounded-xl"
          style={{ boxShadow: '0 4px 16px rgba(242,101,34,0.35)' }}>
          {t('Enregistrer les modifications')}
        </button>
