            );
          }
          return (
            <a key={item.label}
              className={`flex items-center gap-3 px-4 py-3 rounded-lg text-base font-medium ${isActive ? 'bg-secondary text-primary' : 'text-foreground'}`}>
              <Icon i={item.icon} size={18} className={isActive ? 'text-primary' : 'text-muted-foreground'} />
              {item.label}
            </a>
          );
        })}
      </nav>
      <div className="px-3 mt-4">
        <div className="flex items-center gap-3 px-4 py-3">
          <UserAvatar gender="male" ageGroup="25-35" heritage="African" index={0} className="w-9 h-9 rounded-lg" />
          <div className="min-w-0">
            <p className="text-sm font-semibold text-foreground truncate">{t('Kofi Mensah')}</p>
            <p className="text-xs text-muted-foreground truncate">{t('kofi@email.com')}</p>
          </div>
        </div>
      </div>
    </div>
  );
}

